# Generated by build.py from recipe.yml for recipe imap-keep-a-mailbox-off-smtp. Do not edit.
Set-Location $PSScriptRoot
[IO.File]::WriteAllText((Join-Path $PWD 'hi.eml'), "From: app@example.com`nTo: viewer@example.com`nSubject: Hello`n`nA test message.`n")
$server0 = Start-Process surl -ArgumentList '--mail-domain', 'example.com', '--mailbox', '"viewer@example.com:viewpass;protocols=imap"', '--mailbox', 'app@example.com:apppass', 'imap://127.0.0.1:8080/', 'smtp://127.0.0.1:8081/', 'pop3://127.0.0.1:8082/' -PassThru -NoNewWindow
Start-Sleep 1
curl.exe -sS --crlf -u app@example.com:apppass --mail-from app@example.com --mail-rcpt viewer@example.com -T hi.eml smtp://127.0.0.1:8081/example.com
try { curl.exe -sS -u viewer@example.com:viewpass "imap://127.0.0.1:8080/INBOX;UID=1;SECTION=TEXT" } finally { Stop-Process $server0 }
